var text = "No lemon, no melon";
var left = 0;
var right = text.length - 1;
var ok = true;
while (left < right) {
  if (!/[a-z]/i.test(text.charAt(left))) {
    left++;
  } else if (!/[a-z]/i.test(text.charAt(right))) {
    right--;
  } else {
    if (text.charAt(left).toLowerCase() !== text.charAt(right).toLowerCase()) {
      ok = false;
    }
    left++;
    right--;
  }
}
console.log(ok);

